$put('units',['unit_id'=>1,'carinderia_id'=>1,'unit_name'=>'Kilogram','symbol'=>'kg']);$put('inventory_items',['inventory_item_id'=>1,'carinderia_id'=>1,'unit_id'=>1,'name'=>'Raw rice']);$put('suppliers',['supplier_id'=>1,'carinderia_id'=>1,'name'=>'Market']);
